def set_no_device(
    record: dict[str, str],
    *,
    source: str,
    review_state: str = "confirmed",
    view: str | None = None,
) -> None:
    record.update(
        {
            "status": "no_device",
            "bbox_x1": "",
            "bbox_y1": "",
            "bbox_x2": "",
            "bbox_y2": "",
            "source": source,
            "review_state": review_state,
