@app.post("/v1/capture/negative/start")
async def start_negative_capture() -> JSONResponse:
    store: NegativeCaptureStore = app.state.negative_capture
    session_id = store.start()
    return JSONResponse({"ok": True, "session_id": session_id, "count": store._count})


@app.post("/v1/capture/negative")
async def capture_negative(request: Request) -> JSONResponse:
    payload = await request.body()
    source_timestamp_ms = int(
        request.headers.get("x-source-timestamp-ms", round(time.time() * 1000))
    )
    try:
        captured = app.state.negative_capture.save(payload, source_timestamp_ms)
    except (RuntimeError, ValueError) as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=400)
    return JSONResponse(
        {
            "ok": True,
            "session_id": captured.session_id,
            "filename": captured.filename,
            "count": captured.count,
            "width": captured.width,
            "height": captured.height,
        }
    )


@app.post("/v1/capture/negative/stop")
async def stop_negative_capture() -> JSONResponse:
