+      } catch (error) { setStatus("无法打开摄像头：" + error.message); }
+    }
+    async function startDatasetCapture(label) {
+      if (!stream) { setStatus("请先启动摄像头。"); return; }
+      try {
+        const response = await fetch("/v1/capture/session/start", {
+          method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({label})
+        });
+        const data = await response.json();
+        if (!data.ok) { setStatus("无法开始采集：" + data.error); return; }
+        captureMode = label; captureCount = 0;
+        document.querySelector("#capture-count").textContent = "0/10";
+        updateCaptureButtons(true);
+        await refreshCaptureStatus();
+        setStatus(\`正在采集第 \${data.session_ordinal}/6 段\${label === "device" ? "有设备画面" : "无设备背景"}，10 帧后自动停止。\`);
+        captureTimer = setInterval(captureDatasetFrame, 1000);
+      } catch (error) { setStatus("采集启动失败：" + error.message); }
+    }
+    function captureDatasetFrame() {
+      if (!captureTimer || captureBusy || !video.videoWidth) return;
+      captureBusy = true;
+      jpegBlob(async function(blob) {
+        try {
+          if (!blob) throw new Error("摄像头没有返回图像");
+          const response = await fetch("/v1/capture/session/frame", {
+            method:"POST",
+            headers:{"Content-Type":"image/jpeg","x-source-timestamp-ms":String(Date.now())},
+            body:blob
+          });
+          const data = await response.json();
+          if (!data.ok) throw new Error(data.error);
+          captureCount = data.count;
+          document.querySelector("#capture-count").textContent = \`\${captureCount}/10\`;
+          await refreshCaptureStatus();
+          if (data.complete) await stopDatasetCapture(true);
+        } catch (error) {
+          setStatus("采集帧失败：" + error.message);
+          await stopDatasetCapture(false);
+        } finally { captureBusy = false; }
+      });
+    }
+    async function stopDatasetCapture(automatic=false) {
+      if (captureTimer) { clearInterval(captureTimer); captureTimer = null; }
+      try {
+        const response = await fetch("/v1/capture/session/stop", {method:"POST"});
+        const data = await response.json();
+        renderCaptureSummary(data.summary || {});
+        setStatus(automatic
+          ? \`本段已自动保存 \${data.count} 帧。请改变场景后采集下一段。\`
+          : \`本段已停止，共保存 \${data.count || 0} 帧；不足 10 帧的段不会通过数据门禁。\`);
+      } catch (error) { setStatus("停止采集失败：" + error.message); }
+      captureMode = null; updateCaptureButtons(false);
+    }
+    async function stop() {
+      if (captureTimer) await stopDatasetCapture(false);
+      clearInterval(timer); cancelAnimationFrame(raf);
+      if (socket) socket.close();
+      if (stream) stream.getTracks().forEach(function(track) { track.stop(); });
+      socket = null; stream = null; latest = null;
+      startButton.disabled = false; stopButton.disabled = true; updateCaptureButtons(false);
+      setStatus("摄像头已停止。");
+    }
+
+    startButton.addEventListener("click", start);
+    stopButton.addEventListener("click", stop);
+    captureDeviceButton.addEventListener("click", function() { startDatasetCapture("device"); });
+    captureNegativeButton.addEventListener("click", function() { startDatasetCapture("no_device"); });
+    captureStopButton.addEventListener("click", function() { stopDatasetCapture(false); });
+    fetch("/health")
+      .then(function(response) { return response.json(); })
+      .then(function(data) {
